// Un petit message de bienvenue sur trois lignes, à l'ancienne.
// Il faut un \n à chaque fin de ligne, et parfois un + pour continuer.
String message = "Bienvenue sur DevRoad.\n"
        + "Choisis un parcours pour commencer.\n"
        + "Bon apprentissage.\n";

System.out.print(message);
// Affiche :
// Bienvenue sur DevRoad.
// Choisis un parcours pour commencer.
// Bon apprentissage.

// Le même petit objet JSON, écrit sans text block.
// Chaque guillemet du JSON doit être échappé en \" : illisible.
String json = "{\n"
        + "  \"nom\": \"Ada\",\n"
        + "  \"niveau\": 3\n"
        + "}";

System.out.println(json);
// Affiche :
// {
//   "nom": "Ada",
//   "niveau": 3
// }

// Comparé à la version avec \n et +, on lit directement le texte.
String message = """
        Bienvenue sur DevRoad.
        Choisis un parcours pour commencer.
        Bon apprentissage.
        """;

System.out.print(message);
// Affiche exactement les trois lignes, chacune suivie d'un saut de ligne.

// CORRECT : on passe à la ligne juste après les """ d'ouverture.
String ok = """
        Bonjour
        """;

// ERREUR DE COMPILATION : du texte colle les guillemets d'ouverture.
// String casse = """Bonjour
//         """;
//
// Java refuse : il faut un saut de ligne juste après les """ d'ouverture.

// Les guillemets de FERMETURE, eux, peuvent être collés au texte ou seuls sur leur ligne.
String aussiOk = """
        Bonjour""";

// Dans le code, tout le bloc est indenté de 8 espaces pour l'alignement.
// La ligne la moins indentée donne la marge, et ces 8 espaces sont retirés.
String html = """
        <ul>
          <li>Java</li>
          <li>SQL</li>
        </ul>
        """;

System.out.print(html);
// Affiche, SANS les 8 espaces de décor, mais EN GARDANT les 2 espaces
// voulus devant les <li> (ils sont au delà de la marge) :
// <ul>
//   <li>Java</li>
//   <li>SQL</li>
// </ul>

// Fermeture ALIGNÉE avec le contenu : marge = décalage du contenu.
String aligne = """
        Ligne A
        Ligne B
        """;
// Résultat : "Ligne A\nLigne B\n" sans espaces devant.

// Fermeture TOUT À GAUCHE : marge = 0, les espaces de décalage restent.
String colleAGauche = """
        Ligne A
        Ligne B
""";
// Résultat : "        Ligne A\n        Ligne B\n" avec 8 espaces devant chaque ligne.

// Le \ en fin de ligne supprime le saut de ligne : la phrase reste sur UNE ligne.
String phrase = """
        Ceci est une phrase assez longue que l'on coupe dans le code \
        pour la lire, mais qui reste sur une seule ligne une fois affichee.
        """;

System.out.println(phrase);
// Affiche une seule ligne :
// Ceci est une phrase assez longue que l'on coupe dans le code pour la lire, mais qui reste sur une seule ligne une fois affichee.

// Sans \s, les espaces de fin de ligne seraient effacés.
// Ici on veut que chaque label fasse exactement 6 caractères de large.
String menu = """
        Java  \s
        SQL   \s
        YAML  \s
        """;

// Le \s final protège les espaces placés avant lui : les trois labels
// conservent leur alignement sur 6 caractères au lieu d'être rognés.

// Les guillemets du JSON restent tels quels, pas d'échappement, pas de \n.
String json = """
        {
          "utilisateur": "Ada",
          "parcours": "Java moderne",
          "termine": false,
          "niveau": 3
        }
        """;

System.out.println(json);
// On lit la structure du JSON d'un coup d'oeil, comme dans un vrai fichier .json.

// %s marque l'emplacement d'une valeur ; formatted(...) la remplit dans l'ordre.
String modele = """
        {
          "utilisateur": "%s",
          "niveau": %d
        }
        """;

String json = modele.formatted("Ada", 3);
System.out.println(json);
// Affiche :
// {
//   "utilisateur": "Ada",
//   "niveau": 3
// }
// %s insère un texte, %d insère un nombre entier.

